import{_ as o,c as d,a0 as c,o as t}from"./chunks/framework.B6JXc2q-.js";const p=JSON.parse('{"title":"v1.1.7 发布说明","description":"","frontmatter":{},"headers":[],"relativePath":"release/v1.1.7.md","filePath":"release/v1.1.7.md"}'),a={name:"release/v1.1.7.md"};function i(l,e,r,s,n,h){return t(),d("div",null,e[0]||(e[0]=[c('<h1 id="v1-1-7-发布说明" tabindex="-1">v1.1.7 发布说明 <a class="header-anchor" href="#v1-1-7-发布说明" aria-label="Permalink to &quot;v1.1.7 发布说明&quot;">​</a></h1><p>发布日期：2026-09-22 分支：<code>fix/auth-refresh-state-machine</code> 发布源：tag <code>v1.1.7</code> 指向的提交；已验证运行时代码提交 <code>58a4361d</code>（其后仅发布文档变更）。 源 artifact SHA256（基于 <code>58a4361d</code>）：<code>27789efda2e8a34eba28a929600ef3f0c14dd1cc77793cacd754679c1fd8fdce</code></p><hr><h2 id="_1-发布目标" tabindex="-1">1. 发布目标 <a class="header-anchor" href="#_1-发布目标" aria-label="Permalink to &quot;1. 发布目标&quot;">​</a></h2><p>收敛认证刷新状态机、持久认证交换与 QR 后恢复，恢复内网部署的默认可用性，并在不破坏设备媒体数据面的前提下收紧管理与插件边界。</p><p>本版不改变公开 API 形状、播放协调器与来源实现。正式服务器 <code>192.168.7.5</code> 全程未触碰。</p><hr><h2 id="_2-主要变化" tabindex="-1">2. 主要变化 <a class="header-anchor" href="#_2-主要变化" aria-label="Permalink to &quot;2. 主要变化&quot;">​</a></h2><h3 id="_2-1-认证状态机与持久会话" tabindex="-1">2.1 认证状态机与持久会话 <a class="header-anchor" href="#_2-1-认证状态机与持久会话" aria-label="Permalink to &quot;2.1 认证状态机与持久会话&quot;">​</a></h3><ul><li>最小持久能力是 <code>userId + passToken + deviceId</code>。无账号密码时不执行 full login；候选 <code>MiAccount</code> 使用隔离 <code>MemoryTokenStore</code>，不污染现有运行时。</li><li>对外审计路径固定为 <code>used_path=miaccount_persistent_auth_exchange</code>。</li><li>TTL 配置参与调度；unknown TTL 以 12h scheduled 辅助轮转，reactive 401 为主恢复路径。</li><li><code>70016 + captchaUrl=null</code> → <code>credential_session_rejected</code>；<code>87001</code> 或 truthy captcha → <code>interactive_captcha_challenge</code>。scheduled 刷新命中这两类拒绝时保留现有 healthy runtime 并挂起后续自动刷新，等待 verified recovery。</li><li>DNS / connector / 网络 errno 沿异常链分类。健康探测遇到网络瞬断只进入 cooldown，cooldown 后优先重探现有 runtime；不触发持久认证交换、manual gate 或 destructive login，<code>auth_call</code> 也不会因此调度后台恢复。</li><li><code>is_network_error</code> 只把 HTTP 500–599 视为网络状态，不把业务码（如 <code>.code=70016</code>）误判为网络错误。</li><li>QR 保存后使用现有 short session 做 verified atomic rebind；失败保留旧 runtime。</li></ul><h3 id="_2-2-内网部署默认无鉴权" tabindex="-1">2.2 内网部署默认无鉴权 <a class="header-anchor" href="#_2-2-内网部署默认无鉴权" aria-label="Permalink to &quot;2.2 内网部署默认无鉴权&quot;">​</a></h3><ul><li>普通内网部署默认 <code>XIAOMUSIC_DISABLE_HTTPAUTH=true</code>，无需 <code>HTTP_AUTH_HASH</code> 或 <code>HTTP_AUTH_PASSWORD</code> 即可启动；<code>Config</code> 与 CLI 对开关值统一做 <code>strip().lower()</code> 归一。</li><li>只有显式 <code>XIAOMUSIC_DISABLE_HTTPAUTH=false</code> 时 CLI 才要求凭据并 fail-closed。</li><li><code>docker-compose.hardened.yml</code> 是主动选择的鉴权模板，不是默认。</li><li>插件、OpenAPI、插件源路由使用可被 no-auth 模式覆盖的普通 <code>verification</code>：默认内网模式匿名可用，显式启用 Basic 后仍拒绝无效凭据。</li></ul><h3 id="_2-3-设备媒体数据面与管理面分离" tabindex="-1">2.3 设备媒体数据面与管理面分离 <a class="header-anchor" href="#_2-3-设备媒体数据面与管理面分离" aria-label="Permalink to &quot;2.3 设备媒体数据面与管理面分离&quot;">​</a></h3><ul><li>公开读面只包含 <code>/music/*</code>、<code>/picture/*</code>、<code>/static/silence.mp3</code>、<code>/static/search.mp3</code> 与服务端签发的 proxy token；管理写接口仍跟随部署鉴权模式。</li><li>媒体路径使用 <code>Path.resolve()</code> + <code>relative_to()</code>，阻断 <code>..</code> 回溯、绝对路径、兄弟前缀（<code>music</code> vs <code>music_evil</code>）与符号链接越界。</li><li>匿名 <code>/proxy</code> 只接受服务端签发的 <code>t.&lt;token&gt;</code>；legacy base64 URL 仅在显式启用 Basic 时要求有效凭据。</li><li>插件上传拒绝空名、裸 <code>.js</code>、NUL、POSIX/Windows 绝对路径、正反斜杠子目录与目录穿越；文件名预检只检查 multipart part header，不再扫描文件内容（避免正文出现 <code>filename=&quot;a/b&quot;</code> 时误拒合法上传）。</li><li><code>AuthStaticFiles</code> 不再用 <code>assert</code> 执行认证。</li></ul><h3 id="_2-4-依赖与构建" tabindex="-1">2.4 依赖与构建 <a class="header-anchor" href="#_2-4-依赖与构建" aria-label="Permalink to &quot;2.4 依赖与构建&quot;">​</a></h3><ul><li>根 Node lockfile：axios <code>1.20.0</code>、follow-redirects <code>1.16.0</code>、form-data <code>4.0.6</code>、qs <code>6.16.0</code>、undici <code>7.29.1</code>；官方 registry <code>npm audit --omit=dev</code> 为 0。</li><li>Node 安全门禁覆盖 redirect 敏感头、form-data CRLF、qs GHSA-4mjr、axios prototype gadget。</li><li>ARMv7 使用 Alpine builder/runner，并补齐 <code>cargo</code> 与 <code>linux-headers</code>。</li><li>正式 AMD64 / ARM64 / ARMv7 镜像由 <code>v1.1.7</code> tag CI 构建、测试并发布，本机不再手工构建多架构镜像。</li></ul><hr><h2 id="_3-本地验证" tabindex="-1">3. 本地验证 <a class="header-anchor" href="#_3-本地验证" aria-label="Permalink to &quot;3. 本地验证&quot;">​</a></h2><ul><li>全量 pytest：<code>1191 passed / 106 failed / 2 skipped / 1 warning</code>（本版开工基线 <code>1177/106/2</code>，未新增失败；<code>106 failed</code> 为仓库既有基线问题）。</li><li>Node 安全测试：<code>10 passed</code>。</li><li>Ruff（变更文件）、<code>compileall</code>、<code>git diff --check</code>：通过。</li><li>无凭据 <code>git archive</code> 源 artifact SHA256：<code>27789efda2e8a34eba28a929600ef3f0c14dd1cc77793cacd754679c1fd8fdce</code>。</li></ul><hr><h2 id="_4-测试服务器现场验收" tabindex="-1">4. 测试服务器现场验收 <a class="header-anchor" href="#_4-测试服务器现场验收" aria-label="Permalink to &quot;4. 测试服务器现场验收&quot;">​</a></h2><ul><li>服务器：<code>192.168.7.178</code>（测试专用）。正式服务器未触碰。</li><li>Compose project：<code>xiaomusic_core_smoke</code>；端口 <code>58090</code>。</li><li>候选镜像：<code>xiaomusic-core:v1.1.7-final-rc</code>，amd64，image ID <code>sha256:a68950d22fcdc258c2cfeed8e94ce46d3d80b62f2685e6436c4f04b0e317613d</code>。</li><li>容器 <code>StartedAt=2026-09-22T01:20:22Z</code>（JST 10:20:22），<code>restart_count=0</code>。</li><li>镜像内自检：Python import <code>xiaomusic</code> 版本 <code>1.1.7</code>；Node <code>v24.18.1</code>；Node 安全测试 10/10。</li></ul><p>隔离无凭据启动（不挂载部署配置、不提供任何 <code>HTTP_AUTH_*</code>）：</p><ul><li><code>/getversion=200</code>、<code>/api/js-plugins=200</code>，证明无凭据也能启动并匿名可用。</li></ul><p>部署后匿名面：</p><table tabindex="0"><thead><tr><th>路径</th><th>结果</th></tr></thead><tbody><tr><td><code>/getversion</code></td><td>200，<code>version=1.1.7</code></td></tr><tr><td><code>/</code></td><td>302（跟随重定向后 200）</td></tr><tr><td><code>/api/js-plugins</code></td><td>200</td></tr><tr><td><code>/api/admin/v1/auth/status</code></td><td>200</td></tr><tr><td><code>/music/&lt;test&gt;.mp3</code></td><td>200</td></tr><tr><td><code>/picture/&lt;test&gt;.jpg</code></td><td>200</td></tr><tr><td><code>/static/silence.mp3</code>、<code>/static/search.mp3</code></td><td>200</td></tr></tbody></table><p>边界：</p><table tabindex="0"><thead><tr><th>用例</th><th>结果</th></tr></thead><tbody><tr><td><code>/proxy?urlb64=t.&lt;invalid&gt;</code></td><td>400</td></tr><tr><td><code>/music/%2E%2E/&lt;sibling&gt;/&lt;file&gt;</code>（兄弟前缀越界）</td><td>404</td></tr><tr><td>上传 <code>../&lt;name&gt;.js</code></td><td>400，且未落盘</td></tr><tr><td>上传正文含 <code>filename=&quot;a/b&quot;</code> 的合法 <code>.js</code></td><td>200，内容完整落盘</td></tr></tbody></table><p>认证状态与日志：连续运行超过 3 小时 30 分钟后仍为 <code>auth_state=healthy</code>，<code>recovery_failure_count=0</code>、<code>probe_failure_count=0</code>、<code>retry_count=0</code>、<code>lock_counter=0</code>，health/keepalive probe 均为 <code>ok</code>。首次 scheduled refresh 按预期收到一次 <code>70016</code> 后进入 <code>scheduled_refresh_suspended=true</code>，此后未重复刺激登录；日志中 <code>70016</code> 计数为 1，<code>认证失败</code>、<code>87001</code>、<code>Keepalive: 认证不健康</code> 与 Traceback 均为 0。唯一 <code>ERROR</code> 行来自验收临时插件被 runner 加载时的提示，测试文件已删除。</p><p>现场清理与凭据：临时媒体、插件与兄弟目录已全部删除；<code>.env</code>、<code>conf/setting.json</code> 权限为 600。</p><p>回滚坐标：</p><ul><li>回滚镜像：<code>xiaomusic-core:rollback-v1.1.7-security-20260922-004135</code></li><li>救援备份：<code>backups/env-before-final-20260922-102021</code>、<code>backups/setting-before-final-20260922-102021.json</code>、<code>backups/compose-before-final-20260922-102021.yml</code></li><li>回滚 compose：<code>docker-compose.v1.1.7-internal-rollback.yml</code></li><li>候选 compose：<code>docker-compose.v1.1.7-final.yml</code></li></ul><p>部署脚本带失败自动回滚；本次执行中因验收脚本自身断言写错（<code>/</code> 期望 200、<code>/proxy</code> 参数名、picture cache 路径）触发过三次回滚，均恢复到内网无鉴权镜像，修正断言后全量通过。这三次是脚本缺陷，不是产品缺陷。</p><hr><h2 id="_5-发布流程" tabindex="-1">5. 发布流程 <a class="header-anchor" href="#_5-发布流程" aria-label="Permalink to &quot;5. 发布流程&quot;">​</a></h2><ol><li>候选分支已 push 到 <code>Akari787/xiaomusic-core</code>；无斜杠验证分支的 AMD64 CI 已完成构建、Python import 与 Node 安全测试。</li><li>fast-forward 合入 <code>main</code> 并 push。</li><li>打 annotated tag <code>v1.1.7</code> 并 push。</li><li>tag CI 构建并测试 <code>amd64</code>、<code>arm64</code>、<code>armv7</code>，随后发布 Docker Hub 多架构镜像（<code>v1.1.7</code> / <code>latest</code> / <code>stable</code>）与 GitHub Release（release notes 取自 CHANGELOG 对应章节）。</li></ol><hr><h2 id="_6-已知限制与未做事项" tabindex="-1">6. 已知限制与未做事项 <a class="header-anchor" href="#_6-已知限制与未做事项" aria-label="Permalink to &quot;6. 已知限制与未做事项&quot;">​</a></h2><ul><li>仓库既有 <code>106 failed</code> 基线问题不在本版范围。</li><li>启动时 <code>setting.json</code> 与 env 的 <code>disable_httpauth</code> 优先级边界未重构：曾以鉴权模式运行过且残留 <code>disable_httpauth=false</code> 的部署，去掉 env 开关后仍可能回到鉴权模式，需要显式确认配置来源。</li><li>公开媒体面未加扩展名白名单；已认证 + no-auth 模式下 legacy <code>/proxy</code> 未接入 <code>OutboundPolicy</code>（纵深防御项，均不阻断本版）。</li><li>本版未做长时间多日稳定性观察，长时行为以测试服务器持续观察为准。</li></ul>',39)]))}const f=o(a,[["render",i]]);export{p as __pageData,f as default};
